<span class="line"><span style="color:#C678DD;">from</span><span style="color:#ABB2BF;"> d2l </span><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> paddle </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> d2l</span></span>
